const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]); // Approximate center of Wuhan

  const date1_start = '2020-01-01';
  const date1_end = '2020-01-20'; // January 1-20, 2020

  const date2_start = '2020-02-10';
  const date2_end = '2020-02-25'; // February 10-25, 2020

  const S5P_NO2_COLLECTION = 'COPERNICUS/S5P/OFFLINE/L3_NO2';
  const NO2_BAND = 'NO2_column_number_density';
  const QA_BAND = 'qa_value';
  const QA_THRESHOLD = 0.75; // Recommended quality threshold for NO2 data

  // 2. Data Acquisition & Check for Period 1
  let collection1 = ee.ImageCollection(S5P_NO2_COLLECTION)
    .filterBounds(wuhan)
    .filterDate(date1_start, date1_end)
    .filter(ee.Filter.gt(QA_BAND, QA_THRESHOLD))
    .select(NO2_BAND);

  const size1 = await collection1.size().getInfo();
  if (size1 === 0) {
    console.log("No images found for Jan 1-20, 2020 in Wuhan with sufficient quality.");
    console.log("C1");
    return;
  }

  // 2. Data Acquisition & Check for Period 2
  let collection2 = ee.ImageCollection(S5P_NO2_COLLECTION)
    .filterBounds(wuhan)
    .filterDate(date2_start, date2_end)
    .filter(ee.Filter.gt(QA_BAND, QA_THRESHOLD))
    .select(NO2_BAND);

  const size2 = await collection2.size().getInfo();
  if (size2 === 0) {
    console.log("No images found for Feb 10-25, 2020 in Wuhan with sufficient quality.");
    console.log("C1");
    return;
  }

  // 3. Processing: Calculate mean NO2 for each period
  // We'll take the median of the collection to reduce noise, then reduce over the region.
  const median1 = collection1.median();
  const median2 = collection2.median();

  // Check for C2 (No Valid Pixels) before reducing.
  // This is implicit in reduceRegion's behavior: if no valid pixels, it returns null.
  // We'll check the result of reduceRegion for null.

  const scale = 1000; // Use a reasonable scale for atmospheric data

  const meanReducer = ee.Reducer.mean();

  const val1_obj = await median1.reduceRegion({
    reducer: meanReducer,
    geometry: wuhan,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const val2_obj = await median2.reduceRegion({
    reducer: meanReducer,
    geometry: wuhan,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const val1 = val1_obj ? val1_obj[NO2_BAND] : null;
  const val2 = val2_obj ? val2_obj[NO2_BAND] : null;

  // 4. Validation & Final Answer
  if (val1 === null || isNaN(val1) || val2 === null || isNaN(val2)) {
    console.log(`Mean NO2 for Jan: ${val1}, Mean NO2 for Feb: ${val2}`);
    console.log("Calculation failed or no valid pixels remain after processing for one or both periods.");
    console.log("C3");
    return;
  }

  console.log(`Jan 1-20, 2020 Images: ${size1}`);
  console.log(`Feb 10-25, 2020 Images: ${size2}`);
  console.log(`Mean NO2 (mol/m^2) in Jan 1-20, 2020: ${val1.toFixed(8)}`);
  console.log(`Mean NO2 (mol/m^2) in Feb 10-25, 2020: ${val2.toFixed(8)}`);

  if (val2 < val1) {
    console.log("A"); // Yes, NO2 decreased
  } else {
    console.log("B"); // No, NO2 did not decrease (stayed same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
